const $=id=>document.getElementById(id),video=$('broadcast');let recordings=[],selected=0,wantsPlay=false,loadVersion=0;
function hour(start,seconds=0){const d=new Date(start.replace(' ','T')+'-04:00');return new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit',second:seconds?'2-digit':undefined}).format(new Date(d.getTime()+seconds*1000))}
function describe(r,i){return i===0?'The first breaking reports':r.title.split(' : CNN :')[0]}
function updateClock(){const r=recordings[selected];if(r)$('clock').textContent='≈ '+hour(r.start,Math.max(0,video.currentTime))+' EDT'}
function setState(s){$('state').textContent=s}
function showError(message){$('loading').hidden=true;$('error').hidden=false;$('errorText').textContent=message;setState('PLAYBACK UNAVAILABLE')}
function play(){wantsPlay=true;$('startScreen').hidden=true;const version=loadVersion;video.play().catch(()=>{if(version!==loadVersion)return;wantsPlay=false;setState('PRESS PLAY TO CONTINUE');$('loading').hidden=true})}
function load(index,autoplay=false){selected=index;wantsPlay=autoplay;loadVersion++;video.pause();const r=recordings[index];$('error').hidden=true;$('loading').hidden=!autoplay;$('recording').textContent='CNN · '+describe(r,index);$('part').textContent=String(index+1).padStart(2,'0')+' / '+recordings.length;$('source').href=r.source;$('errorSource').href=r.source;$('previous').disabled=index===0;$('next').disabled=index===recordings.length-1;document.querySelectorAll('.reel-item').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-current',String(i===index))});$('clock').textContent='≈ '+hour(r.start,r.offset)+' EDT';setState(autoplay?'LOADING RECORDING':'READY TO WATCH');video.src=r.url;video.load()}
video.addEventListener('loadedmetadata',()=>{video.currentTime=recordings[selected].offset;updateClock();if(wantsPlay)play()});video.addEventListener('playing',()=>{wantsPlay=true;$('loading').hidden=true;$('error').hidden=true;$('startScreen').hidden=true;setState('ORIGINAL BROADCAST')});video.addEventListener('waiting',()=>{if(wantsPlay){$('loading').hidden=false;setState('BUFFERING')}});video.addEventListener('pause',()=>{if(!video.ended)setState('PAUSED')});video.addEventListener('timeupdate',updateClock);video.addEventListener('error',()=>showError('The original recording could not load. Try again or open this recording at the Internet Archive.'));
video.addEventListener('ended',()=>{if(selected+1<recordings.length)load(selected+1,true);else{wantsPlay=false;setState('END OF THIS ARCHIVE SEQUENCE')}});
$('begin').onclick=play;$('next').onclick=()=>{if(selected+1<recordings.length){$('startScreen').hidden=true;load(selected+1,true)}};$('previous').onclick=()=>{if(selected>0){$('startScreen').hidden=true;load(selected-1,true)}};$('retry').onclick=()=>load(selected,true);$('reel').onclick=e=>{const b=e.target.closest('[data-index]');if(b){$('startScreen').hidden=true;load(Number(b.dataset.index),true)}};$('theater').onclick=()=>{document.body.classList.toggle('theater');$('theater').textContent=document.body.classList.contains('theater')?'Standard view ⛶':'Expand view ⛶'};$('about').onclick=()=>$('details').showModal();$('close').onclick=()=>$('details').close();
fetch('archive.json').then(r=>{if(!r.ok)throw new Error('Archive index unavailable');return r.json()}).then(data=>{if(!Array.isArray(data)||!data.length)throw new Error('No recordings indexed');recordings=data;$('reel').innerHTML=data.map((r,i)=>`<button class="reel-item" data-index="${i}"><time>${hour(r.start,r.offset)}</time><span><strong>${describe(r,i)}</strong><small>${Math.round((r.duration-r.offset)/60)} min · original recording</small></span></button>`).join('');$('coverage').textContent=data.length+' original recordings · '+((data.reduce((n,r)=>n+r.duration-r.offset,0))/3600).toFixed(1)+' hours';$('begin').disabled=false;$('begin').textContent='▶  Watch original coverage';load(0)}).catch(()=>{$('begin').textContent='Archive index unavailable';showError('The recording index could not be loaded. Reload this page or visit the Internet Archive.');$('errorSource').href='https://archive.org/details/911'});
